/// Checks if a file share directory exists
/// </summary>
/// <param name = "_shareDirectoryClient">The file share directory</param>
/// <returns>True if it exists</returns>
public static boolean checkFileShareDirectoryExists(ShareDirectoryClient _shareDirectoryClient)
{        
    boolean                         ret;
    ;

    try
