/// <summary>
/// Removes the fileshare name part from the trimmed directory
/// </summary>
/// <param name = "_fileShareName">The name of the file share</param>
/// <param name = "_directoryName">The name of the directory</param>
/// <returns>The trimmed directory</returns>
public static OMGFileShareDirectory trimDirectory(OMGFileShareName _fileShareName, OMGFileShareDirectory _directoryName)
{
    OMGFileShareDirectory trimmedDirectory = _directoryName;
    if (subStr(_directoryName, 2, strLen(_fileShareName)) == _fileShareName)
    {
        trimmedDirectory = strDel(_directoryName, 1, strLen(_fileShareName) + 1);
    }
    return trimmedDirectory;
}
